originalExecute:
({ path, content }) =>
    Effect.gen(function* () {
      const { container, pendingWrites } = yield* WebContainerPlayground.get
      yield* FiberMap.run(
        pendingWrites,
        path,
        Effect.gen(function* () {
          yield* Effect.sleep(WRITE_DEBOUNCE_MILLIS)
          yield* Effect.tryPromise(() => container.fs.writeFile(path, content))
          if (path !== STYLES_CSS_PATH) {
            const stylesContent = yield* Effect.tryPromise(() =>
              container.fs.readFile(STYLES_CSS_PATH, 'utf-8'),
            )
            yield* Effect.tryPromise(() =>
              container.fs.writeFile(STYLES_CSS_PATH, stylesContent),
            )
          }
        }).pipe(
          Effect.catch(error =>
            Effect.logError(
              `[playground] Debounced write failed for ${path}:`,
              error,
            ),
          ),
        ),
        { startImmediately: true },
      )
      return Message.ScheduledWritePlaygroundFile()
    }).pipe(
      Effect.catchTag('ResourceNotAvailable', () =>
        Effect.succeed(
          Message.FailedWritePlaygroundFile({
            reason: 'WebContainer not yet ready',
          }),
        ),
      ),
    )

scaffold:
import { Effect, FiberMap } from 'effect'
import type {} from './context.d.ts'
const STYLES_CSS_PATH = 'src/styles.css'
const WRITE_DEBOUNCE_MILLIS = 250
declare const Message: Readonly<{
    ScheduledWritePlaygroundFile: (() => Readonly<{ _tag: 'Scheduled' }>) & Readonly<{ Type: Readonly<{ _tag: 'Scheduled' }> }>
    FailedWritePlaygroundFile: ((input: Readonly<{ reason: string }>) => Readonly<{ _tag: 'Failed'; reason: string }>) & Readonly<{ Type: Readonly<{ _tag: 'Failed'; reason: string }> }>
  }>
export const definition: Readonly<{ execute: (args: Readonly<{ path: string; content: string }>) => Effect.Effect<typeof Message.ScheduledWritePlaygroundFile.Type | typeof Message.FailedWritePlaygroundFile.Type, never, WebContainerPlaygroundService> }> = { execute: __EXECUTE_CALLBACK__ }

